import sys

# Verifica se há argumentos além do nome do script
if len(sys.argv) > 1:
    # Itera sobre todos os argumentos (excluindo o nome do script)
    for arg in sys.argv[1:]:
        # Remove espaços em branco à direita e imprime o argumento
        print(arg.rstrip())
else:
    print("Nenhum argumento fornecido.")

